% AulaTeX - Actividad 3 materializada desde planeacion S3, notas y guia LEO.
% Consigna S3: Resena sobre el contenido de los articulos constitucionales que
% sustentan el derecho de la seguridad social en Mexico. Tecnica didactica:
% Resena (100 tecnicas UnADM). Ponderacion 10/100. APA 7.
% Estructura LINEAL (LEO Uniandes): introduccion -> exposicion (sintesis) ->
% evaluacion critica (juicio sustentado) -> conclusion -> referencias.
% Elementos obligatorios (planeacion): (1) fundamento constitucional (art. 123
% apartado A fr. XXIX, apartado B fr. XI y art. 4 CPEUM); (2) parafrasis de esos
% articulos; (3) reflexion sobre su importancia como derecho humano; (4)
% legislacion secundaria (LSS, LISSSTE, LISSFAM).
\documentclass[12pt,letterpaper,oneside]{article}
\usepackage[margin=2.35cm]{geometry}
\usepackage[utf8]{inputenc}
\usepackage[T1]{fontenc}
\usepackage[spanish,es-tabla]{babel}
\usepackage[scaled=.96]{helvet}
\renewcommand{\familydefault}{\sfdefault}
\usepackage{setspace}
\usepackage{graphicx}
\usepackage[table]{xcolor}
\usepackage{booktabs}
\usepackage{array}
\usepackage{longtable}
\usepackage{pdflscape}
\usepackage{csquotes}
\usepackage{enumitem}
\usepackage[most]{tcolorbox}
\usepackage{hyperref}
\usepackage[authoryear,round]{natbib}

\definecolor{unadmGreenDark}{HTML}{174A3A}
\definecolor{unadmGreen}{HTML}{5F8F3A}
\definecolor{unadmGold}{HTML}{B88A2A}
\definecolor{unadmPaper}{HTML}{F6F7F2}
\definecolor{unadmInk}{HTML}{1F2A24}
\definecolor{unadmRowAlt}{HTML}{EDF1E7}
\hypersetup{colorlinks=true,linkcolor=unadmGreenDark,citecolor=unadmGreenDark,urlcolor=unadmGreenDark}
\setlength{\parindent}{0pt}
\setlength{\parskip}{0.72em}
\onehalfspacing
\bibliographystyle{plainnat}
\newcommand{\documenttitle}{El fundamento constitucional de la seguridad social en Mexico}
\newcommand{\documentsubtitle}{Resena academica: sintesis del articulado y valoracion critica como derecho humano}
\newcommand{\documentsubject}{Actividad 3 - Derecho a la Seguridad Social}

\newcolumntype{L}[1]{>{\raggedright\arraybackslash}p{#1}}

% ==========================================================================
% PRODUCTO ANIDADO: la RESENA es el producto de la actividad y va enmarcada
% dentro del cuerpo del reporte (patron homologo al forobox de la Actividad 1).
% El REPORTE conserva su propia Introduccion y Conclusion; la RESENA conserva
% su estructura oficial (ficha bibliografica, titulo, introduccion, cuerpo,
% conclusiones) DENTRO del recuadro.
% ==========================================================================
\newtcolorbox{resenabox}[1][]{%
  enhanced, breakable,
  colback=unadmPaper, colframe=unadmGreenDark,
  boxrule=1pt, leftrule=4pt, arc=2pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  fonttitle=\bfseries\color{white},
  colbacktitle=unadmGreenDark,
  attach boxed title to top left={xshift=8pt, yshift=-2pt},
  boxed title style={colback=unadmGreenDark, arc=1pt},
  title={Producto: rese\~na academica}, #1}

% Ficha bibliografica de la obra reseñada (recuadro superior de la resena).
% Uso: \fichabibliografica{obra}{autoria}{editorial/fuente}{lugar}{ano}{edicion/version}
\newcommand{\fichabibliografica}[6]{%
  \begin{tcolorbox}[enhanced, colback=unadmRowAlt, colframe=unadmGreen,
    boxrule=0.6pt, arc=1pt, left=8pt, right=8pt, top=5pt, bottom=5pt,
    fonttitle=\bfseries\color{unadmGreenDark}, colbacktitle=unadmRowAlt,
    coltitle=unadmGreenDark, title={Ficha bibliogr\'afica de la obra rese\~nada}]
  {\small
  \begin{tabular}{@{}p{0.24\linewidth}p{0.70\linewidth}@{}}
    \textbf{Obra rese\~nada:} & #1 \\
    \textbf{Autor\'ia:} & #2 \\
